bash -lc 'cd /src/libxml2 && python3 - <<"PY"
from pathlib import Path
path = Path("xinclude.c")
data = path.read_text(encoding="utf-8")
old = """\		if (doc == NULL) {
		    ctxt->incTab[nr]->xptr = xptr;
		    ctxt->incTab[nr]->inc = NULL;
		} else {
		    ctxt->incTab[nr]->inc =
			xmlXIncludeCopyXPointer(ctxt, ctxt->doc, doc, xptr);
		    xmlXPathFreeObject(xptr);
		}
"""
new = """\		/*
		 * Don't cache evaluated XPointer results (xmlXPathObjectPtr)
		 * across XInclude processing steps.
		 *
		 * The nodeset inside an XPath object holds raw xmlNodePtr.
		 * During XInclude processing, earlier substitutions can unlink/free
		 * nodes in the document. If we keep the evaluated object for a later
		 * "late computation" step, xmlXIncludeCopyXPointer may dereference
		 * stale pointers, causing a heap-use-after-free.
		 *
		 * Instead, immediately materialize a standalone copy node list.
		 */
		ctxt->incTab[nr]->inc =
		    xmlXIncludeCopyXPointer(ctxt, ctxt->doc,
					 (doc != NULL) ? doc : ctxt->doc, xptr);
		xmlXPathFreeObject(xptr);
		ctxt->incTab[nr]->xptr = NULL;
"""
